import app from 'flarum/forum/app';
import Component from "flarum/common/Component";
import HumanizeUtils from '../../common/utils/HumanizeUtils';
export default class RewardList extends Component {
  view(vnode) {
    const humanize = HumanizeUtils.getInstance(app);
    return m("div", {
      className: "collector-reward"
    }, m("div", {
      className: "collector-reward-title"
    }, m("i", {
      class: "fas fa-gift"
    }), " ", app.translator.trans("xypp-collector.forum.reward.reward")), humanize.humanizeReward(this.attrs.rewards).map(e => m("div", null, e)));
  }
}
flarum.reg.add('xypp-trust-levels', 'collector/forum/components/RewardList', RewardList);