import app from "flarum/forum/app";
export function triggerCondition(key, value) {
  return triggerConditions({
    [key]: value
  });
}
export function triggerConditions(records) {
  const rec = Object.keys(records).map(key => {
    return {
      name: key,
      value: records[key]
    };
  });
  return app.request({
    url: app.forum.attribute('apiUrl') + "/collector-condition",
    method: "POST",
    body: {
      data: rec
    }
  });
}
flarum.reg.add('xypp-trust-levels', 'collector/forum/utils/frontendTrigger', { triggerCondition: triggerCondition,triggerConditions: triggerConditions, });