import app from 'flarum/forum/app';
import Component from "flarum/common/Component";
import { OPERATOR } from "../../common/types/data";
import HumanizeUtils from '../../common/utils/HumanizeUtils';
import userValueUtil from '../utils/userValueUtil';
export default class ConditionList extends Component {
  view(vnode) {
    const humanize = HumanizeUtils.getInstance(app);
    return m("div", {
      className: "collector-condition"
    }, m("div", {
      className: "collector-condition-title"
    }, m("i", {
      class: "fas fa-tasks"
    }), " ", app.translator.trans("xypp-collector.forum.condition.condition")), this.attrs.conditions.map(condition => {
      return m("div", {
        className: "collector-condition-line"
      }, m("span", null, humanize.humanizeCondition(condition)), this.progress(condition, humanize));
    }));
  }
  progress(condition, humanize) {
    if (!this.attrs.conditionMap) return "";
    const valueHelper = new userValueUtil(humanize, this.attrs.conditionMap);
    let value = valueHelper.getValue(condition);
    const satisfy = this.conditionOp(value, condition.operator, condition.value);
    if (satisfy) {
      return m("span", {
        className: "collector-progress-satisfy"
      }, "[", m("i", {
        class: "fas fa-check"
      }), "]");
    }
    return m("span", {
      className: "collector-progress-not-satisfy"
    }, "[", value, "/", condition.value, "]");
  }
  conditionOp(value1, op, value2) {
    switch (op) {
      case OPERATOR.EQUAL:
        return value1 == value2;
      case OPERATOR.GREATER_THAN:
        return value1 > value2;
      case OPERATOR.GREATER_THAN_OR_EQUAL:
        return value1 >= value2;
      case OPERATOR.LESS_THAN:
        return value1 < value2;
      case OPERATOR.LESS_THAN_OR_EQUAL:
        return value1 <= value2;
      case OPERATOR.NOT_EQUAL:
        return value1 != value2;
    }
  }
}
flarum.reg.add('xypp-trust-levels', 'collector/forum/components/ConditionList', ConditionList);